88	export const useContentfulEntries = <T>(contentType: string, preview = false) => {
89	  const [data, setData] = useState<T[] | null>(null);
90	  const [isLoading, setIsLoading] = useState(true);
91	  const [error, setError] = useState<Error | null>(null);
92	
93	  useEffect(() => {
94	    const controller = new AbortController();
95	
96	    const fetchEntries = async () => {
97	      const config = getContentfulConfig();
98	      if (!config.spaceId || !config.accessToken) {
99	        setError(new Error('Contentful configuration missing'));
100	        setIsLoading(false);
101	        return;
102	      }
103	
104	      try {
105	        const { spaceId, accessToken, previewAccessToken, environment } = config;
106	        const baseUrl = preview ? 'https://preview.contentful.com' : 'https://cdn.contentful.com';
107	        const token = preview ? previewAccessToken : accessToken;
108	
109	        // Include assets in the response
110	        const url = `${baseUrl}/spaces/${spaceId}/environments/${environment}/entries?content_type=${contentType}&access_token=${token}&include=2`;
111	
112	        const response = await fetch(url, { signal: controller.signal });
113	
114	        if (!response.ok) {
115	          const errorText = await response.text();
116	          console.error('Contentful API error response:', errorText);
117	          throw new Error(`Contentful API error: ${response.status}`);
118	        }
119	
120	        const result: ContentfulEntriesResponse = await response.json();
121	
122	        // Resolve linked assets
123	        const resolvedItems = result.items.map((item) => {
124	          const resolvedItem = { ...item };
125	
126	          if (item.fields) {
127	            Object.keys(item.fields).forEach((fieldKey) => {
128	              const fieldValue = item.fields[fieldKey] as ContentfulLink;
129	              if (fieldValue?.sys?.type === 'Link' && fieldValue?.sys?.linkType === 'Asset') {
130	                const assetId = fieldValue.sys.id;
131	                const linkedAsset = result.includes?.Asset?.find((asset) => asset.sys.id === assetId);
132	                if (linkedAsset) {
133	                  resolvedItem.fields[fieldKey] = linkedAsset;
134	                }
135	              }
136	            });
137	          }
138	
139	          return resolvedItem;
140	        });
141	
142	        setData(resolvedItems as T[]);
143	      } catch (err) {
144	        if (err instanceof DOMException && err.name === 'AbortError') return;
145	        console.error('Contentful fetch error:', err);
146	        setError(err instanceof Error ? err : new Error('Unknown error'));
147	      } finally {
148	        setIsLoading(false);
149	      }
150	    };
151	
152	    void fetchEntries();
153	    return () => controller.abort();
154	  }, [contentType, preview]);
155	
156	  return { data, isLoading, error };
157	};
